export type EffectFunction<Prev, Next extends Prev = Prev> = (v: Next, p?: Prev) => (() => void) | void;
export type EffectBundle<Prev, Next extends Prev = Prev> = {
    effect: EffectFunction<Prev, Next>;
    error: (err: unknown, cleanup: () => void) => void;
};
export declare function createEffect<const T>(compute: (v: undefined | NoInfer<T>) => T, effectFn: EffectFunction<NoInfer<T>, T> | EffectBundle<NoInfer<T>, T>): void;
export declare function createMemo<T>(compute: (v: undefined | NoInfer<T>) => T): () => T;
